CREATE TABLE public."AdminSession" (id text NOT NULL, token text NOT NULL, email text NOT NULL, "expiresAt" timestamp(3) without time zone NOT NULL, "createdAt" timestamp(3) without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL);
CREATE TABLE public."Answer" (id text NOT NULL, "userId" text NOT NULL, "questionId" text NOT NULL, "quizAttemptId" text NOT NULL, "selectedOption" integer NOT NULL, "isCorrect" boolean, "createdAt" timestamp(3) without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL);
CREATE TABLE public."AppSettings" (key text NOT NULL, value text NOT NULL, description text, "updatedAt" timestamp with time zone DEFAULT now() NOT NULL, "updatedBy" text);
CREATE TABLE public."DailyPayment" (id text NOT NULL, "userId" text NOT NULL, amount double precision DEFAULT 2.0 NOT NULL, status text NOT NULL, "paymentMethod" text, "transactionId" text, "expiresAt" timestamp(3) without time zone NOT NULL, "createdAt" timestamp(3) without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL, "updatedAt" timestamp(3) without time zone NOT NULL);
CREATE TABLE public."Notification" (id text NOT NULL, "userId" text NOT NULL, title text NOT NULL, message text NOT NULL, type text NOT NULL, read boolean DEFAULT false NOT NULL, link text, "createdAt" timestamp without time zone DEFAULT now() NOT NULL, "updatedAt" timestamp without time zone DEFAULT now() NOT NULL);
CREATE TABLE public."Payment" (id text NOT NULL, "userId" text NOT NULL, amount double precision NOT NULL, status text NOT NULL, "paymentMethod" text, "transactionId" text, "createdAt" timestamp(3) without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL, "updatedAt" timestamp(3) without time zone NOT NULL);
CREATE TABLE public."Prize" (id text NOT NULL, name text NOT NULL, description text, "imageUrl" text, "modelUrl" text, type text NOT NULL, "pointsRequired" integer NOT NULL, "isActive" boolean DEFAULT true NOT NULL, "createdAt" timestamp(3) without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL, "updatedAt" timestamp(3) without time zone NOT NULL, category text DEFAULT 'general'::text NOT NULL, stock integer DEFAULT 0 NOT NULL, status text DEFAULT 'published'::text NOT NULL, value double precision DEFAULT 0 NOT NULL);
CREATE TABLE public."PrizeRedemption" (id text NOT NULL, "userId" text NOT NULL, "prizeId" text NOT NULL, "pointsUsed" integer NOT NULL, status text NOT NULL, "fullName" text, "whatsappNumber" text, address text, "requestedAt" timestamp(3) without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL, "processedAt" timestamp(3) without time zone, notes text, "createdAt" timestamp(3) without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL, "updatedAt" timestamp(3) without time zone NOT NULL, "processedBy" text, "trackingNumber" text, "deliveryDate" timestamp(3) without time zone);
CREATE TABLE public."Question" (id text NOT NULL, "quizId" text NOT NULL, text text NOT NULL, options text NOT NULL, "correctOption" integer, "hasCorrectAnswer" boolean DEFAULT false NOT NULL, status text DEFAULT 'active'::text NOT NULL, "createdAt" timestamp(3) without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL, "updatedAt" timestamp(3) without time zone NOT NULL);
CREATE TABLE public."QuestionAttempt" (id text NOT NULL, "userId" text NOT NULL, "questionId" text NOT NULL, "quizId" text NOT NULL, "selectedOption" integer NOT NULL, "isCorrect" boolean, "attemptedAt" timestamp(3) without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL, "createdAt" timestamp with time zone DEFAULT now());
CREATE TABLE public."Quiz" (id text NOT NULL, title text NOT NULL, description text, duration integer DEFAULT 30 NOT NULL, "passingScore" integer DEFAULT 70 NOT NULL, status text DEFAULT 'active'::text NOT NULL, "createdAt" timestamp(3) without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL, "updatedAt" timestamp(3) without time zone NOT NULL, "accessPrice" double precision DEFAULT 2.0 NOT NULL, "startsAt" timestamp with time zone, "prizeId" text, "isBumperPrize" boolean DEFAULT false NOT NULL, "quizType" text DEFAULT 'normal'::text NOT NULL);
CREATE TABLE public."QuizAttempt" (id text NOT NULL, "userId" text NOT NULL, "quizId" text NOT NULL, score integer DEFAULT 0 NOT NULL, points integer DEFAULT 0 NOT NULL, "isCompleted" boolean DEFAULT false NOT NULL, "isEvaluated" boolean DEFAULT false NOT NULL, "completedAt" timestamp(3) without time zone, "paymentId" text, "dailyPaymentId" text, "createdAt" timestamp(3) without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL, "updatedAt" timestamp(3) without time zone NOT NULL);
CREATE TABLE public."RateLimitEntry" (id text NOT NULL, key text NOT NULL, "createdAt" timestamp(3) without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL);
CREATE TABLE public."SecurityEvent" (id text NOT NULL, type text NOT NULL, "userId" text, ip text, "userAgent" text, endpoint text, details text, severity text, "timestamp" timestamp(3) without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL, "createdAt" timestamp(3) without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL);
CREATE TABLE public."User" (id text NOT NULL, name text, email text NOT NULL, password text, phone text, "dateOfBirth" timestamp(3) without time zone, "profilePicture" text, points integer DEFAULT 0 NOT NULL, "createdAt" timestamp(3) without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL, "updatedAt" timestamp(3) without time zone NOT NULL, "walletBalance" double precision DEFAULT 0 NOT NULL, "authProvider" text);
CREATE TABLE public."WalletTransaction" (id text NOT NULL, "userId" text NOT NULL, amount double precision NOT NULL, "paymentMethod" text NOT NULL, "transactionId" text NOT NULL, status text DEFAULT 'pending'::text NOT NULL, "proofImage" text, "adminNotes" text, "processedAt" timestamp(3) without time zone, "processedBy" text, "createdAt" timestamp(3) without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL, "updatedAt" timestamp(3) without time zone NOT NULL, type text DEFAULT 'deposit'::text NOT NULL, description text, notes text);
CREATE TABLE public."Winning" (id text NOT NULL, "userId" text NOT NULL, "quizId" text NOT NULL, "prizeId" text NOT NULL, claimed boolean DEFAULT false NOT NULL, "createdAt" timestamp(3) without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL, "updatedAt" timestamp(3) without time zone NOT NULL);
CREATE TABLE public."QuizWinner" (id text DEFAULT (gen_random_uuid())::text NOT NULL, "quizId" text NOT NULL, "prizeId" text NOT NULL, "userId" text NOT NULL, score integer NOT NULL, "completedAt" timestamp with time zone, "selectionMethod" text NOT NULL, "selectedBy" text, seed text NOT NULL, "selectedAt" timestamp with time zone DEFAULT now() NOT NULL, "notificationSent" boolean DEFAULT false NOT NULL, "prizeRedemptionId" text, "createdAt" timestamp with time zone DEFAULT now() NOT NULL, "updatedAt" timestamp with time zone DEFAULT now() NOT NULL);
ALTER TABLE public."AdminSession" ADD PRIMARY KEY (id); ALTER TABLE public."Answer" ADD PRIMARY KEY (id); ALTER TABLE public."AppSettings" ADD PRIMARY KEY (key);
ALTER TABLE public."DailyPayment" ADD PRIMARY KEY (id); ALTER TABLE public."Notification" ADD PRIMARY KEY (id); ALTER TABLE public."Payment" ADD PRIMARY KEY (id);
ALTER TABLE public."Prize" ADD PRIMARY KEY (id); ALTER TABLE public."PrizeRedemption" ADD PRIMARY KEY (id); ALTER TABLE public."Question" ADD PRIMARY KEY (id);
ALTER TABLE public."QuestionAttempt" ADD PRIMARY KEY (id); ALTER TABLE public."Quiz" ADD PRIMARY KEY (id); ALTER TABLE public."QuizAttempt" ADD PRIMARY KEY (id);
ALTER TABLE public."RateLimitEntry" ADD PRIMARY KEY (id); ALTER TABLE public."SecurityEvent" ADD PRIMARY KEY (id); ALTER TABLE public."User" ADD PRIMARY KEY (id);
ALTER TABLE public."WalletTransaction" ADD PRIMARY KEY (id); ALTER TABLE public."Winning" ADD PRIMARY KEY (id); ALTER TABLE public."QuizWinner" ADD PRIMARY KEY (id);
