ALTER TABLE public."Answer" ADD FOREIGN KEY ("quizAttemptId") REFERENCES "QuizAttempt"(id) ON UPDATE CASCADE ON DELETE CASCADE;
ALTER TABLE public."DailyPayment" ADD FOREIGN KEY ("userId") REFERENCES "User"(id) ON UPDATE CASCADE ON DELETE CASCADE;
ALTER TABLE public."Question" ADD FOREIGN KEY ("quizId") REFERENCES "Quiz"(id) ON UPDATE CASCADE ON DELETE CASCADE;
ALTER TABLE public."QuestionAttempt" ADD FOREIGN KEY ("questionId") REFERENCES "Question"(id) ON UPDATE CASCADE ON DELETE CASCADE;
ALTER TABLE public."QuestionAttempt" ADD FOREIGN KEY ("userId") REFERENCES "User"(id) ON UPDATE CASCADE ON DELETE CASCADE;
ALTER TABLE public."QuestionAttempt" ADD FOREIGN KEY ("quizId") REFERENCES "Quiz"(id) ON UPDATE CASCADE ON DELETE CASCADE;
ALTER TABLE public."QuizAttempt" ADD FOREIGN KEY ("quizId") REFERENCES "Quiz"(id) ON UPDATE CASCADE ON DELETE CASCADE;
ALTER TABLE public."QuizAttempt" ADD FOREIGN KEY ("userId") REFERENCES "User"(id) ON UPDATE CASCADE ON DELETE CASCADE;
ALTER TABLE public."WalletTransaction" ADD FOREIGN KEY ("userId") REFERENCES "User"(id) ON UPDATE CASCADE ON DELETE CASCADE;
